{"cards": [{"node_code": "N_23f2ab2ed6c0e62f", "definition": "研究传感器前端信号获取电路，涵盖惠斯通电桥等桥路拓扑、激励源设计、传感器阻抗匹配及信号初始提取技术。", "boundary": "聚焦于信号链最前端的“源-接口”环节，关注如何将传感器物理量转化为微弱电信号并优化传输条件。边界在于不涉及后续放大滤波或A/D转换，也不涉及传感器内部换能机理。若研究重点在于传感器材料或结构，归入“传感器与换能器”；若涉及信号放大，归入“放大、滤波、隔离与抗混叠”。", "includes": ["惠斯通电桥、全桥/半桥/单桥电路设计及灵敏度分析", "恒压/恒流激励源设计、噪声抑制及驱动电路", "传感器与调理电路间的阻抗匹配、偏置电路及信号提取"], "excludes": ["传感器内部的物理换能原理或材料特性研究", "信号放大、滤波或模数转换电路设计", "多通道采集系统的时间同步或系统级架构"], "sibling_distinctions": [{"other_code": "N_793f8689afb7a2b6", "rule": "本节点关注信号源端的桥路激励与阻抗匹配；兄弟节点关注信号获取后的放大、滤波及隔离处理。"}, {"other_code": "N_3a2da3b6f9d2f642", "rule": "本节点关注模拟信号的前端提取与匹配；兄弟节点关注模拟信号到数字信号的转换过程及量化特性。"}], "cross_boundary_rule": "若研究涉及传感器内部结构对桥路性能的影响，主挂载“传感器与换能器”；若仅关注外部电路如何激励和匹配传感器，主挂载本节点。"}, {"node_code": "N_793f8689afb7a2b6", "definition": "研究测量信号在模拟域的中间处理技术，涵盖信号放大、有源/无源滤波、电气隔离及抗混叠电路设计。", "boundary": "聚焦于信号链中段的“信号质量优化”环节，关注如何增强微弱信号、抑制噪声及保护后端电路。边界在于不涉及前端桥路激励或后端A/D转换算法。若研究重点在于滤波器数学模型或数字信号处理，归入“信号处理”；若涉及具体隔离器件物理结构，可关联“传感器与换能器”但主挂载本节点。", "includes": ["仪表放大器、程控增益放大器及低噪声放大电路设计", "有源/无源滤波器设计、抗混叠滤波器及频率响应优化", "电气隔离技术、光耦/磁耦隔离及信号完整性保障"], "excludes": ["传感器内部的物理换能原理或材料特性研究", "模数转换器(ADC)的量化误差或动态范围设计", "采集后的数字信号处理算法或系统辨识模型"], "sibling_distinctions": [{"other_code": "N_23f2ab2ed6c0e62f", "rule": "本节点关注信号获取后的放大与滤波；兄弟节点关注信号源端的桥路激励与阻抗匹配。"}, {"other_code": "N_3a2da3b6f9d2f642", "rule": "本节点关注模拟信号的调理与保护；兄弟节点关注模拟信号到数字信号的转换过程及量化特性。"}], "cross_boundary_rule": "若研究重点在于滤波器的数字实现或算法，主挂载“信号处理”；若重点在于模拟电路实现及硬件性能，主挂载本节点。"}, {"node_code": "N_3a2da3b6f9d2f642", "definition": "研究模拟信号到数字信号转换的核心技术，涵盖模数转换器(ADC)原理、量化误差分析、动态范围设计及采样保持电路。", "boundary": "聚焦于信号链末端的“模数转换”环节，关注转换精度、速度及动态性能。边界在于不涉及前端信号调理或后端数字处理算法。若研究重点在于ADC芯片内部电路结构，可关联“放大、滤波、隔离与抗混叠”但主挂载本节点；若涉及多通道同步采样策略，归入“数据采集与同步”。", "includes": ["ADC架构(Σ-Δ、SAR、Pipeline等)原理及性能指标分析", "量化噪声、信噪比(SNR)、无杂散动态范围(SFDR)及有效位数(ENOB)设计", "采样保持电路、时钟抖动影响及过采样/欠采样技术"], "excludes": ["传感器内部的物理换能原理或材料特性研究", "前端桥路激励、放大或滤波电路设计", "采集后的数字信号处理算法或系统级同步控制"], "sibling_distinctions": [{"other_code": "N_23f2ab2ed6c0e62f", "rule": "本节点关注模拟到数字的转换过程；兄弟节点关注信号源端的桥路激励与阻抗匹配。"}, {"other_code": "N_793f8689afb7a2b6", "rule": "本节点关注转换精度与动态范围；兄弟节点关注转换前的信号放大、滤波及隔离。"}], "cross_boundary_rule": "若研究重点在于ADC在特定采集卡中的集成应用或系统级性能评估，可挂载至“数据采集与同步”；若重点在于ADC器件本身的转换原理、量化误差或电路设计，主挂载本节点。"}]}
